{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈砚清",
      "role": "protagonist",
      "identity": "法租界公董局法医，32岁",
      "traits": ["冷峻理性", "细节强迫症", "情感压抑", "求知欲极强"],
      "overt_motivation": "查明三起密室溺毙案的真相，将凶手绳之以法",
      "covert_motivation": "寻找自己身世的真相，确认自己是否'正常'",
      "secret_fear": "发现自己与某种不可控的力量/实验有关",
      "misperception_of_other": "认为苏晚音是通灵会骗局的参与者，在利用他",
      "hidden_connection": "两人都是1842年哈特利实验的后裔，是'筛选机制'的 competing candidates"
    },
    {
      "name": "苏晚音",
      "role": "deuteragonist",
      "identity": "通灵师/神秘档案研究者，28岁",
      "traits": ["神秘疏离", "洞察人心", "亦正亦邪", "背负秘密"],
      "overt_motivation": "阻止通灵会继续用规则操控人命",
      "covert_motivation": "找到哈特利档案的完整版本，终结百年实验",
      "secret_fear": "自己也是实验的一部分，无法逃脱命运",
      "misperception_of_other": "认为沈砚清只是被利用的调查工具，迟早会被牺牲",
      "hidden_connection": "她的曾祖父是哈特利的助手，家族守护档案秘密近百年"
    }
  ],
  "supporting_characters": [
    {
      "name": "周慕云",
      "function": "助力",
      "identity": "法租界巡捕房探长",
      "description": "沈砚清的旧识，务实派，提供案件调查的官方渠道支持"
    },
    {
      "name": "钱守义",
      "function": "阻碍",
      "identity": "通灵会会长",
      "description": "表面是通灵会领袖，实则是哈特利实验的'执行者'后代，负责筛选候选人"
    },
    {
      "name": "陈伯年",
      "function": "助力",
      "identity": "租界档案馆管理员",
      "description": "老档案员，帮助沈砚清找到1842年哈特利手稿的关键人物"
    },
    {
      "name": "托马斯·哈特利",
      "function": "反转点",
      "identity": "1842年英国东印度公司军医（已故）",
      "description": "七条规则的原始编写者，跨种族医学实验的发起者，通过日记和档案'现身'"
    }
  ],
  "relationship_dynamics": "沈砚清与苏晚音的关系在'互相利用'和'唯一知己'之间摇摆。初期苏晚音主动接近沈砚清提供线索，沈砚清怀疑她是凶手同伙；中期两人发现彼此都在调查哈特利档案，形成脆弱的合作关系；后期揭露两人都是实验后裔，是'竞争关系'但也是唯一能理解彼此处境的人。最终苏晚音为让沈砚清逃脱而牺牲自己，完成'惨胜'结局。"
}
"}

{"content": "{
  "act_one": {
    "description": "建立民国上海租界世界观，引入三起密室溺毙案，沈砚清发现七条通灵守则，初步调查通灵会，在档案馆发现1842年哈特利手稿——第一次认知反转：规则不是凶手编写，而是百年前的遗产",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "无水之溺",
        "core_event": "沈砚清被召至法租界第一起密室现场，发现死者肺部充满液体但现场无水源，墙纸上浮现七条通灵守则",
        "emotional_tone": "阴冷悬疑",
        "key_scenes": ["深夜出警", "密室勘查", "发现守则", "初步验尸"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第七条的矛盾",
        "core_event": "沈砚清逐条分析守则，发现第三条与第五条逻辑互斥，开始怀疑规则是凶手的心理操控手段",
        "emotional_tone": "理性分析中暗藏不安",
        "key_scenes": ["守则抄录", "逻辑推演", "与周慕云讨论"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "通灵会",
        "core_event": "沈砚清潜入通灵会调查，遇见苏晚音，她声称能'解读'规则的真正含义",
        "emotional_tone": "神秘诡异",
        "key_scenes": ["通灵会会场", "与苏晚音初次交锋", "钱守义的警告"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "第二具尸体",
        "core_event": "第二起密室案发生，手法完全相同，沈砚清发现两间密室的墙纸守则笔迹一致",
        "emotional_tone": "紧迫感升级",
        "key_scenes": ["第二现场", "笔迹比对", "苏晚音主动提供线索"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "1842年8月29日",
        "core_event": "沈砚清在租界档案馆找到哈特利手稿，发现规则雏形，日期是《南京条约》签订当日",
        "emotional_tone": "震惊与困惑",
        "key_scenes": ["档案馆夜访", "陈伯年协助", "发现手稿", "第一次反转"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "受试者筛选协议",
        "core_event": "手稿内容显示这是'Subject Selection Protocol'，沈砚清开始怀疑自己也被纳入筛选",
        "emotional_tone": "自我怀疑萌芽",
        "key_scenes": ["翻译手稿", "发现'第七代'字样", "检查自己手臂的针孔"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "苏晚音的警告",
        "core_event": "苏晚音告诉沈砚清规则是'活'的，越研究越会被卷入，劝他停止调查",
        "emotional_tone": "暧昧与威胁并存",
        "key_scenes": ["深夜会面", "苏晚音透露部分真相", "沈砚清拒绝放弃"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "第三具尸体",
        "core_event": "第三起密室案发生，死者是通灵会核心成员，现场守则上多了一行字：'你已入选'",
        "emotional_tone": "恐惧与决心",
        "key_scenes": ["第三现场", "发现新增文字", "沈砚清确认自己是目标"],
        "turning_point": "第一幕转折：沈砚清意识到自己不是调查者，而是被筛选的对象，案件从'破案'转为'自救'"
      }
      ],
    "turning_point": "沈砚清发现1842年哈特利手稿，规则不是凶手编写而是百年遗产；第三现场出现'你已入选'字样，确认自己是目标"
  },
  "act_two": {
    "description": "沈砚清与苏晚音形成脆弱合作，深入调查哈特利实验真相，发现密室手法的物理解释，同时发现自己身世异常——第二次认知反转：没有超自然，只有精心设计的百年犯罪",
    "key_chapters": [
      {
        "chapter_number": 9,
        "chapter_title": "脆弱的同盟",
        "core_event": "沈砚清与苏晚音达成合作，她透露自己家族与哈特利档案的关系",
        "emotional_tone": "互相试探中的信任建立",
        "key_scenes": ["交换信息", "苏晚音展示家族日记", "确定共同目标"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "盐水之溺",
        "core_event": "沈砚清重新验尸，发现死者肺部氯化钠浓度远超海水，推断是注射高浓度盐水导致肺水肿",
        "emotional_tone": "科学理性对抗神秘氛围",
        "key_scenes": ["实验室复检", "化学分析", "推断作案手法"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "密室的缝隙",
        "core_event": "周慕云发现三间密室天花板都有检修口，凶手从通风管道进入，'密室'是假象",
        "emotional_tone": "真相逐步剥离",
        "key_scenes": ["建筑勘查", "管道追踪", "发现凶手藏身处"]
      },
      {
        "chapter_number": 12,
        "chapter_title": "热敏涂料",
        "core_event": "沈砚清发现墙纸守则是热敏涂料，室温变化时显现，'自动浮现'是人为操控",
        "emotional_tone": "超自然假象被戳破",
        "key_scenes": ["涂料分析", "实验验证", "第二次反转铺垫"]
      },
      {
        "chapter_number": 13,
        "chapter_title": "钱守义的秘密",
        "core_event": "调查发现钱守义是哈特利实验执行者的后代，负责'筛选'候选人",
        "emotional_tone": "阴谋浮出水面",
        "key_scenes": ["跟踪钱守义", "发现秘密据点", "截获通信"]
      },
      {
        "chapter_number": 14,
        "chapter_title": "收养记录",
        "core_event": "沈砚清发现自己的收养记录异常，亲生父母是租界医院的'实验对象'",
        "emotional_tone": "身份危机",
        "key_scenes": ["查阅出生记录", "发现篡改痕迹", "寻找亲生父母信息"]
      },
      {
        "chapter_number": 15,
        "chapter_title": "哈特利的日记",
        "core_event": "苏晚音找到哈特利完整日记，揭露实验目的：筛选特定基因携带者进行'传承'",
        "emotional_tone": "震撼与愤怒",
        "key_scenes": ["日记翻译", "实验目的揭露", "沈砚清身世确认"]
      },
      {
        "chapter_number": 16,
        "chapter_title": "第六条的暗示",
        "core_event": "沈砚清意识到自己一直在执行第六条（每日默念），这是心理暗示的'锚点'",
        "emotional_tone": "自我认知的崩塌",
        "key_scenes": ["回忆自己何时开始默念", "分析心理暗示机制"]
      },
      {
        "chapter_number": 17,
        "chapter_title": "竞争者",
        "core_event": "苏晚音透露她也是候选人，两人是'竞争关系'，只能有一人'通过筛选'",
        "emotional_tone": "信任危机与情感张力",
        "key_scenes": ["苏晚音坦白", "沈砚清的复杂反应", "关系重新定义"]
      },
      {
        "chapter_number": 18,
        "chapter_title": "钱守义的对峙",
        "core_event": "沈砚清与钱守义正面交锋，钱守义承认自己是执行者，但说'真正的筛选者另有其人'",
        "emotional_tone": "紧张对峙",
        "key_scenes": ["废弃医院对峙", "钱守义透露更多信息", "苏晚音救场"]
      },
      {
